export const TENSIONS = [
  { a: ['ring', 'dromon'], b: ['city', 'archedemos'], text: 'On the ring you held that Plato rigs the case against a decent idea of law. On the city you held that he means well by everyone in it. A reader can hold both, but owes an account of why a writer who is unfair in one place is to be trusted in the next.' },
  { a: ['cave', 'sannion'], b: ['city', 'archedemos'], text: 'You held that every city is a cave, the good one included, and also that the good city is a place where everyone is better off. If its citizens are prisoners watching shadows, it is hard to see what "better off" means for them.' },
  { a: ['poetry', 'sannion'], b: ['city', 'dromon'], text: 'You held that Socrates is a poet making images all night, and also that his city is a literal program. If the ring, the ship, and the cave are poems, the city may be one too.' },
  { a: ['back', 'archedemos'], b: ['city', 'sannion'], text: 'You held that the philosopher loses nothing by going back down to rule, and also that the city he would rule cannot exist. Then there is nowhere for him to go back down to.' },
  { a: ['back', 'kleio'], b: ['ring', 'kleio'], text: 'You held that the ring sets the test Socrates must pass, and that the return to the cave is where he fails it: justice there asks a person to act against his own good. Those two fit together, and together they say the book does not prove what it set out to prove.' },
  { a: ['cave', 'theano'], b: ['city', 'phanias'], text: 'You read the cave as a picture of schooling and the whole book as a book about schooling. Those fit. The cost is that the classes, the lie, and the philosopher kings all have to be read as a frame.' },
  { a: ['writing', 'phanias'], b: ['poetry', 'phanias'], text: 'You held that the page is the cure for the poem. Then the story against writing has to be set aside as a mistake of Plato’s about his own tools, as Havelock says.' },
  { a: ['poetry', 'dromon'], b: ['back', 'dromon'], text: 'Twice you asked the helmsman’s question: who keeps the list, and who checks the ruler. Notice that this reading says little about the question the night began with, which was whether justice is good for the just person.' },
];

